import Foundation

// swiftlint:disable line_length
// The base64 payloads in `AssetImageFixturePinnedData` below are
// machine-generated, single-token data literals: they cannot be reflowed
// without corrupting the encoded bytes, so `line_length` is disabled for
// exactly this generated-data block rather than raised globally.

/// Pinned, pre-generated bytes for ``AssetImageFixtureBuilder``'s "happy
/// path" real/decodable PNG, JPEG, and AVIF fixtures.
///
/// **Generated, not handwritten.** Every constant below is the verbatim
/// base64 output of running `AssetImageFixtureBuilder`'s own
/// `renderUncached(width:height:utType:)` (a small solid-color bitmap
/// encoded locally via `CGImageDestinationCreateWithData` — never an
/// embedded or fetched official image binary) for the exact
/// width/height/format combinations this test suite uses, captured once
/// on a machine where the system AVIF/HEIF encoder was available and
/// responsive.
///
/// **Why pinned instead of live-encoded at test time:** `validAVIF`'s
/// underlying `CGImageDestinationFinalize` call is backed by a shared
/// system codec service (ImageIO → `CMPhoto` → VideoToolbox tile
/// compression). Under this suite's full ~600-test concurrent run on a
/// loaded/shared machine, that shared service was observed (via `sample`
/// stack inspection) to serialize or stall for minutes even with only one
/// caller at a time — an external system/environment reliability issue,
/// not a bug in this package's production or test code. Pinning removes
/// the test suite's runtime dependency on that system service entirely,
/// while still exercising the exact same full ImageIO decode path in
/// production code, since the bytes are genuinely valid, decodable
/// images — not synthetic/malformed shells.
///
/// **Regenerating/adding a fixture:** run
/// `AssetImageFixtureBuilder.renderUncached(width:height:utType:)` locally
/// (for example from a throwaway `swift` script or test) for the desired
/// dimensions/format, base64-encode the result, and add it here. `render`
/// falls back to a live, on-demand `renderUncached` call for any
/// width/height/format combination not listed below, so adding a new test
/// with a novel size never silently breaks — it is simply not immune to
/// the system-codec reliability issue above until pinned.
enum AssetImageFixturePinnedData {
    static let avif4x4 =
        ""
    static let avif8x8 =
        ""
    static let avif3x4 =
        ""

    static let png4x4 =
        "iVBORw0KGgoAAAANSUhEUgAAAAQAAAAECAYAAACp8Z5+AAAAAXNSR0IArs4c6QAAADhlWElmTU0AKgAAAAgAAYdpAAQAAAABAAAAGgAAAAAAAqACAAQAAAABAAAABKADAAQAAAABAAAABAAAAADmpNw4AAAAFklEQVQIHWO8oa/wnwEJMCGxwUzCAgCN2gIuovJD0AAAAABJRU5ErkJggg=="
    static let png6x4 =
        "iVBORw0KGgoAAAANSUhEUgAAAAYAAAAECAYAAACtBE5DAAAAAXNSR0IArs4c6QAAADhlWElmTU0AKgAAAAgAAYdpAAQAAAABAAAAGgAAAAAAAqACAAQAAAABAAAABqADAAQAAAABAAAABAAAAAAymEz/AAAAF0lEQVQIHWO8oa/wnwELYMIiBhYiXQIA0zoCLl4SUG8AAAAASUVORK5CYII="
    static let png6x6 =
        "iVBORw0KGgoAAAANSUhEUgAAAAYAAAAGCAYAAADgzO9IAAAAAXNSR0IArs4c6QAAADhlWElmTU0AKgAAAAgAAYdpAAQAAAABAAAAGgAAAAAAAqACAAQAAAABAAAABqADAAQAAAABAAAABgAAAABIWB+fAAAAF0lEQVQIHWO8oa/wnwELYMIiBhaihwQAQNsCMscXwjEAAAAASUVORK5CYII="
    static let png6x9 =
        "iVBORw0KGgoAAAANSUhEUgAAAAYAAAAJCAYAAAARml2dAAAAAXNSR0IArs4c6QAAADhlWElmTU0AKgAAAAgAAYdpAAQAAAABAAAAGgAAAAAAAqACAAQAAAABAAAABqADAAQAAAABAAAACQAAAADKCIhOAAAAF0lEQVQIHWO8oa/wnwELYMIiBhYaYhIA5q0COJ663DAAAAAASUVORK5CYII="
    static let png100x100 =
        ""
    static let png200x200 =
        ""

    static let jpeg4x4 =
        ""
    static let jpeg12x5 =
        ""
    static let jpeg8x8 =
